/**
 * Build `docs/evidence/…-atc-objecttype-confirmed.md` from probe manifests.
 *
 * This exists as a committed script rather than something typed into a shell
 * because it makes claims. The first two versions of that document were
 * generated by throwaway code and each carried a defect nobody could review:
 * one summarised the confirmation chain instead of showing it, and one printed
 * a transport timeout as though it were the server's answer — the same mistake
 * that had just been fixed inside `probe-atc.ts`, repeated in a place where
 * the fix could not reach.
 *
 * The rule it exists to serve: **a step with no HTTP status is not an
 * observation.** It says the request got no answer, which is a fact about the
 * run and not about ATC, and it may never be printed beside a status code as
 * though the two were comparable.
 *
 * Usage:
 *   node scripts/atc-evidence.mjs atc-probe5 atc-probe6 > docs/evidence/OUT.md
 */

import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const dirs = process.argv.slice(2);
if (dirs.length === 0) {
  process.stderr.write('usage: node scripts/atc-evidence.mjs <probe-dir>…\n');
  process.exit(1);
}

const runs = new Map();
for (const d of dirs) {
  const manifest = JSON.parse(readFileSync(join(d, 'manifest.json'), 'utf8'));
  runs.set(d, {
    manifest,
    byStep: new Map(manifest.steps.map((s) => [s.n, s])),
  });
}

const body = (dir, n) => {
  const step = runs.get(dir).byStep.get(n);
  return step?.bodyFile ? readFileSync(join(dir, step.bodyFile), 'utf8') : '';
};

/** A step's outcome, never conflating "no answer" with a status. */
const outcome = (step) =>
  step.status === null
    ? `**no observation** — the request got no answer (${step.error ?? 'no error recorded'}, ${step.durationMs}ms)`
    : `**${step.status}**`;

const worklistId = (url) =>
  (url.match(/worklistId=([0-9A-F]+)/) ??
    url.match(/\/worklists\/([0-9A-F]+)/))?.[1];

const statusIn = (text) => text.match(/runs:status="([^"]+)"/)?.[1];

const ORDER = [
  'class',
  'interface',
  'function_group',
  'package',
  'ddl_source',
  'table',
  'behavior_definition',
];

// Which run confirmed each type first.
const confirmed = new Map();
for (const [dir, { manifest }] of runs) {
  for (const c of manifest.candidates) {
    if (c.confirmed && !confirmed.has(c.key)) confirmed.set(c.key, { dir, c });
  }
}

const out = [];
const say = (...lines) => out.push(...lines);

say(
  '# ATC evidence: `AtcObjectType` confirmed on the cloud trial, 2026-08-17',
  '',
  'Generated by `scripts/atc-evidence.mjs` from the probe manifests. Host redacted; everything',
  "else is the server's own bytes. Raw captures stay out of git (`atc-probe*/` is ignored).",
  '',
  '## What has to be shown, and why a summary will not do',
  '',
  'A type is confirmed when **the run submitted at the URI this client builds** comes back with',
  'that object in **its own** finished worklist. A weaker fact — the type appearing in *some*',
  'worklist — proves the type is checkable but not that the URI is right, and the package run',
  'lists everything in the package, so it can supply that weaker fact for every type at once.',
  '',
  'So each section carries the chain, and the **worklist id is the join**: it appears in the run',
  'request, in the run resource the `Location` points at, and in the worklist read. Same id',
  'throughout, a different id per type.',
  '',
);

for (const key of ORDER) {
  const hit = confirmed.get(key);
  if (!hit) continue;
  const { dir, c } = hit;
  const { manifest, byStep } = runs.get(dir);
  const attempt = c.attempts.find((a) => a.confirmed);
  const runStep = byStep.get(attempt.step);
  const wid = worklistId(runStep.request.url);
  const read = manifest.steps.find(
    (s) =>
      s.step.startsWith(`findings-${key}`) && worklistId(s.request.url) === wid,
  );
  const location = runStep.responseHeaders?.location ?? '';
  const runId = location ? location.replace(/\/$/, '').split('/').pop() : null;
  const statusSteps = manifest.steps.filter(
    (s) =>
      s.step.startsWith(`status-${key}`) &&
      runId &&
      s.request.url.includes(runId),
  );
  const finished =
    statusSteps.find((s) => statusIn(s.bodyPreview ?? '') === 'finished') ??
    statusSteps.at(-1);
  const allObjects = [
    ...body(dir, read.n).matchAll(/<atcobject:object[^>]*>/g),
  ].map((m) => m[0]);
  // For `package`, quote every object the worklist listed rather than only the
  // package itself. The spec's row says the package run confirms the package
  // AND lists what is inside it, and that second half is also the mechanism it
  // cites for the weaker "checked in some worklist" fact — so it has to be
  // visible, not asserted. Raised in review, 2026-08-17.
  const objects =
    key === 'package'
      ? allObjects
      : allObjects.filter((t) =>
          t.toUpperCase().includes(c.representative.name.toUpperCase()),
        );

  say(
    `### \`${key}\` — \`${dir}\`, template \`${c.confirmedBy}\``,
    '',
    `**worklist \`${wid}\`** — the id that joins the four steps.`,
    '',
    '```',
    `1. POST /sap/bc/adt/atc/worklists?checkVariant=…   -> ${wid}`,
    `2. POST /sap/bc/adt/atc/runs?worklistId=${wid}&clientWait=false`,
    `      objectReference adtcore:uri="${attempt.uri}"`,
    `   -> ${runStep.status ?? 'NO ANSWER'}   Location: ${location || '(none)'}`,
    `3. GET  ${finished ? finished.request.url : '(no status read)'}`,
    `   -> ${finished ? (statusIn(finished.bodyPreview ?? '') ?? 'unreadable') : 'n/a'}`,
    `4. GET  /sap/bc/adt/atc/worklists/${wid}?includeExemptedFindings=false`,
    '```',
    '',
    'and step 4 answered with:',
    '',
    '```xml',
    ...objects
      .slice(0, key === 'package' ? objects.length : 1)
      .map((t) => t.replace(/\s+/g, ' ')),
    '```',
    '',
  );

  const backLink = finished
    ? body(dir, finished.n).match(/href="([^"]*\/atc\/worklists\/[^"]*)"/)?.[1]
    : null;
  if (backLink) {
    say(
      `The run resource links back to the same worklist — \`${backLink}\` — so the chain closes`,
      'from both ends.',
      '',
    );
  }
}

say('## The control: a URI that cannot exist', '');
for (const [dir, { manifest }] of runs) {
  const step = manifest.steps.find((s) => s.step === 'run-control-bogus-uri');
  if (step)
    say(
      `- \`${dir}\`: \`/sap/bc/adt/oo/classes/ZZ_NO_SUCH_CLASS_PROBE\` → ${outcome(step)}`,
    );
}
say(
  '',
  'The run that answered shows a **201** — the same answer a real object gets, which is why every',
  'section above cites a worklist and not a status code. A run that got no answer shows nothing',
  'at all and is not evidence in either direction.',
  '',
);

say(
  '## Steps that got no answer',
  '',
  "Recorded because this trial is slow enough to hit the probe's per-request ceiling regularly,",
  'and a timed-out step must never be read as a result:',
  '',
);
for (const [dir, { manifest }] of runs) {
  const dead = manifest.steps.filter((s) => s.status === null);
  say(
    `- \`${dir}\`: ${dead.length} of ${manifest.steps.length} steps — ${
      dead.map((s) => `\`${s.step}\``).join(', ') || 'none'
    }`,
  );
}
say('');

say(
  '## What the system refuses to hold',
  '',
  '```xml',
  '<exc:exception><type id="ExceptionResourceNoAuthorization"/>',
  '  <message lang="EN">You are not authorized to make changes (authorization object S_DEVELOP)</message>',
  '</exc:exception>',
  '```',
  '',
  '`program` and `include` are unmeasurable here rather than unmeasured; they wait on an on-prem',
  'probe.',
  '',
  '## Open questions, as far as these runs took them',
  '',
);
for (const [dir, { manifest }] of runs) {
  for (const s of manifest.steps) {
    if (!s.step.includes('in-flight')) continue;
    say(
      `- \`${dir}\` \`${s.step}\` → ${outcome(s)}, ${s.durationMs}ms, \`${statusIn(s.bodyPreview ?? '') ?? 'unreadable'}\``,
    );
  }
}
say(
  '',
  'A long poll and a plain read started at the same moment came back within ~200ms of each other,',
  'both `running`. Evidence, not a verdict: one pair cannot separate "held" from "slow".',
  '',
);
for (const [dir, { manifest }] of runs) {
  const seen = (manifest.findingStatsSeen ?? [])
    .filter((f) => f.triple)
    .map((f) => `${f.label} = \`${f.triple}\``)
    .join('; ');
  if (seen) say(`- \`${dir}\` FINDING_STATS: ${seen}`);
}
say(
  '',
  "Not decoded: the positions need triples correlated with the findings' priorities, and a",
  'worklist carrying more than one priority.',
  '',
);

let text = out.join('\n');
for (const [, { manifest }] of runs) {
  text = text.split(manifest.system).join('https://<trial>');
}
process.stdout.write(text);
